import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');

const { fontFamily: playfairFamily } = loadPlayfair();



export type TheGapCompoundsProps = Record<string, any>;

const TheGapCompounds: React.FC<TheGapCompoundsProps> = ({
  backgroundColor = "#060F1C",
  transparentBackground = false,
  durationInSeconds = 6,
  innerGlowColor = "#162842",
  outerBgColor = "#060F1C",
  textColor = "#F0E6C8",
  timeMarker1 = "6 months in",
  statement1 = "The gap compounds.",
  timeMarker2 = "12 months in",
  statement2 = "It shows up in your multiple.",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors on background
  const bgStyle: React.CSSProperties = transparentBackground
    ? { backgroundColor: `${backgroundColor}00` }
    : {
        background: `radial-gradient(circle at 30% 50%, ${innerGlowColor} 0%, ${outerBgColor} 70%, ${outerBgColor} 100%)`,
      };

  // Easing function for slow, luxurious motion
  const easeFn = Easing.bezier(0.4, 0, 0.2, 1);

  // Timings & Interpolations
  const hairlineOpacity = interpolate(frame, [0, 0.5 * fps], [0, 0.3], {
    easing: easeFn,
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const u1TimeOpacity = interpolate(
    frame,
    [0.5 * fps, 1.3 * fps],
    [0, 1],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const u1MainOpacity = interpolate(
    frame,
    [0.8 * fps, 1.8 * fps],
    [0, 1],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const u1MainY = interpolate(
    frame,
    [0.8 * fps, 1.8 * fps],
    [12, 0],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const u2TimeOpacity = interpolate(
    frame,
    [2.2 * fps, 3.0 * fps],
    [0, 1],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const u2MainOpacity = interpolate(
    frame,
    [2.5 * fps, 3.6 * fps],
    [0, 1],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const u2MainY = interpolate(
    frame,
    [2.5 * fps, 3.6 * fps],
    [12, 0],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Fade to black at the very end
  const fadeOutEnd = durationInSeconds * fps;
  const fadeOutStart = Math.min((durationInSeconds - 0.6) * fps, fadeOutEnd - 1);
  const fadeOutOpacity = interpolate(
    frame,
    [fadeOutStart, fadeOutEnd],
    [0, 1],
    { easing: easeFn, extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Shared Styles
  const timeStyle: React.CSSProperties = {
    fontFamily: playfairFamily,
    fontWeight: 700,
    fontSize: height * 0.07,
    color: textColor,
    textTransform: "lowercase",
    letterSpacing: "0.02em",
    marginBottom: height * 0.01,
    transition: "none",
  };

  const mainStyle: React.CSSProperties = {
    fontFamily: playfairFamily,
    fontWeight: 400,
    fontSize: height * 0.035,
    color: textColor,
    lineHeight: 1.3,
    transition: "none",
  };

  return (
    <AbsoluteFill style={bgStyle}>
      {/* Main Content Layout */}
      <AbsoluteFill
        style={{
          flexDirection: "row",
          alignItems: "center",
          paddingLeft: width * 0.2,
        }}
      >
        {/* Vertical Hairline */}
        <div
          style={{
            width: 1,
            height: "45%",
            backgroundColor: textColor,
            opacity: hairlineOpacity,
            marginRight: width * 0.04,
            transition: "none",
          }}
        />

        {/* Text Units Container */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            maxWidth: width * 0.55,
          }}
        >
          {/* Unit 1 */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              marginBottom: height * 0.1,
            }}
          >
            <div style={{ ...timeStyle, opacity: u1TimeOpacity }}>
              {timeMarker1}
            </div>
            <div
              style={{
                ...mainStyle,
                opacity: u1MainOpacity,
                transform: `translateY(${u1MainY}px)`,
              }}
            >
              {statement1}
            </div>
          </div>

          {/* Unit 2 */}
          <div style={{ display: "flex", flexDirection: "column" }}>
            <div style={{ ...timeStyle, opacity: u2TimeOpacity }}>
              {timeMarker2}
            </div>
            <div
              style={{
                ...mainStyle,
                opacity: u2MainOpacity,
                transform: `translateY(${u2MainY}px)`,
              }}
            >
              {statement2}
            </div>
          </div>
        </div>
      </AbsoluteFill>

      {/* Master Fade to Black */}
      <AbsoluteFill
        style={{
          backgroundColor: "black",
          opacity: fadeOutOpacity,
          pointerEvents: "none",
        }}
      />
    </AbsoluteFill>
  );
};

export default TheGapCompounds;